DEFINITIONS=[{'symbol': '002932', 'primary': '1225132337', 'pages': [1, 2], 'risk_group': '扣除后营收不足3亿元且亏损，收购尚未完成', 'known_at_anchor': '2025利润三项孰低为负，扣除后营收约2.41亿元，4月22日起退市风险警示。无保留审计不豁免组合财务条件；6月提出现金购买必凯尔100%股权，尚需股东会，且董事会决定暂不召开该次股东会。', 'watch': '核股东会、真实交割和并表日期、新年度扣除后营收及盈利审计；重大资产购买不当司法重整、重组上市或已经完成。', 'supporting': [{'id': '1225132345', 'pages': [3], 'note': '2025财报审计无保留意见，与财务指标触发分别看。'}, {'id': '1225397705', 'pages': [1], 'note': '6月29日董事会通过交易相关议案，6月30日披露，仍需股东会。'}, {'id': '1225397748', 'pages': [1], 'note': '6月30日公告暂不召开股东会；不能把董事会通过当交易完成。'}]}, {'symbol': '600053', 'primary': '1225250914', 'pages': [1, 2], 'risk_group': '负利润与扣除后营收不足3亿元，历史更正另核', 'known_at_anchor': '2025利润孰低为负且扣除后营收不足3亿元，4月30日实施退市风险警示。前期差错更正另使2023归母由盈转亏，2023/2024及2025期中相关报表追溯调整，不影响现金流量表。', 'watch': '核年度真实经营、扣除口径和审计；历史更正与2025触发条件分别核，关键审计事项不当保留审计意见。', 'supporting': [{'id': '1225250266', 'pages': [1, 2], 'note': '2023归母盈亏性质改变；更正后2023/2024审计报告已同日列入正式目录，不延续成仍未出具。'}, {'id': '1225250289', 'pages': [2, 4], 'note': '2025审计为无保留，扫描页人工核读；第4页收入约2.81亿元只是该页约数，不冒充扣除后精确数。'}]}, {'symbol': '600079', 'primary': '1224874140', 'pages': [1, 2], 'risk_group': '历史虚假记载处罚警示，审计事项消除不等于摘帽', 'known_at_anchor': '2025年12月处罚事先告知载明历史财务虚假记载，12月16日起其他风险警示；12月29日收到正式决定。2026年3月专项说明确认2025标准无保留及旧立案强调事项消除，但这不替代处罚警示撤销。', 'watch': '分别核决定作出日、满12个月和重述等申请条件、正式批准与生效；收到日不直接替代作出日，整改和罚款缴纳不当全部摘帽。行情两历史端点精度或复权差异另留。', 'supporting': [{'id': '1224904927', 'pages': [1, 3], 'note': '2025年12月29日收到决定；历史占用本金利息截至2022年4月15日已归还，不当2026新现金。'}, {'id': '1225050666', 'pages': [2, 3], 'note': '扫描专项说明：2025标准无保留，处罚结案及850万元罚款缴纳后旧立案强调事项消除；不认证ST撤销。'}]}, {'symbol': '600080', 'primary': '1225242871', 'pages': [1, 2], 'risk_group': '内控否定意见触发ST，已还占款不等于内控修复', 'known_at_anchor': '2025财报内控被出具否定意见，4月30日起其他风险警示。3956.89万元占款至2025年末已归还，但重复占用仍揭示内控重大缺陷；财报本身另有保留意见，不与内控意见混称。', 'watch': '核整改实效、独立内控审计和正式撤销；另项1800万元投资意向金约定10月31日前退还，不当期初已收。重复整改月报不当多次独立验证。', 'supporting': [{'id': '1225243092', 'pages': [2, 3, 4], 'note': '重复资金占用与已退回、另项意向金未收及退款约定分列；关联方认定公司与审计师看法不强行统一。'}, {'id': '1225243115', 'pages': [2, 3, 4], 'note': '财报保留涉及股权减值、意向金可收回及关联方认定；正文写2025年4月27日出具而末页落款2026年，日期冲突保留，不自行更正。'}, {'id': '1225397185', 'pages': [1, 2, 3], 'note': '6月仍在制度修订、自查整改，连续两年相关内控意见可能升级警示；不把月报当已解除。'}]}]
